def to_bin(n):
    if n == 0:
        return '0'
    s = ''
    while n > 0:
        s = str(n % 2) + s
        n //= 2
    return s

print(to_bin(45))

def detect(bits):
    state = 0
    out = ''
    for b in bits:
        if state == 0:
            state, o = (1, '0') if b == '1' else (0, '0')
        elif state == 1:
            state, o = (1, '0') if b == '1' else (2, '0')
        else:
            state, o = (1, '1') if b == '1' else (0, '0')
        out += o
    return out

print(detect('10101'))
